styles:
:root{--bg:#070807;--bg2:#0a0c0b;--panel:#101311;--paper:#f1eee8;--ink:#f5f2ec;--muted:#969994;--line:rgba(255,255,255,.13);--red:#e81848;--green:#53b879;--green2:#a4d9b7;--greenDeep:#163423;--pad:clamp(20px,3.4vw,58px);--max:1480px;--ease:cubic-bezier(.16,1,.3,1);--font:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}img{display:block;width:100%}button,input,select{font:inherit}.shell{width:min(var(--max),100%);margin:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:#111;padding:10px 14px;transform:translateY(-150%)}.skip:focus{transform:none}.nav{height:82px;position:fixed;inset:0 0 auto;z-index:90;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,8,7,.76);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:18px;letter-spacing:-.04em}.brand img{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0}.nav-links a:hover,.nav-links a:focus-visible{color:white}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;position:relative}.menu-btn:before,.menu-btn span{content:"";position:absolute;left:13px;width:18px;height:1px;background:currentColor}.menu-btn:before{top:18px}.menu-btn span{top:26px}.mobile-menu{display:none;position:fixed;z-index:80;inset:82px 0 0;background:#070807;padding:32px var(--pad)}.mobile-menu.open{display:block}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}.mobile-menu a:last-child{color:var(--red)}
.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 19px;border:1px solid rgba(255,255,255,.24);font-size:13px;transition:.25s var(--ease)}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary{background:var(--red);border-color:var(--red)}.reveal{opacity:0;transform:translateY(22px);transition:opacity .72s var(--ease),transform .72s var(--ease)}.reveal.in{opacity:1;transform:none}
/* HERO */
.hero{min-height:100svh;padding-top:82px;position:relative;overflow:hidden;display:flex;align-items:flex-end;background:#070807}.hero-media{position:absolute;inset:82px 0 0}.hero-media img{height:100%;object-fit:cover;object-position:center 46%;filter:saturate(.72) contrast(1.08) brightness(.45);transform:scale(1.025);will-change:transform}.hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,8,7,.04),rgba(7,8,7,.3) 45%,rgba(7,8,7,.94) 93%),linear-gradient(90deg,rgba(7,8,7,.9),rgba(7,8,7,.12) 67%)}.hero-shell{position:relative;z-index:2;width:min(var(--max),100%);margin:auto;padding:0 var(--pad) clamp(40px,5vw,72px)}.hero-meta{display:flex;justify-content:space-between;gap:20px;border-top:1px solid rgba(255,255,255,.24);padding-top:16px;margin-bottom:clamp(28px,4vw,56px)}.hero h1{font-size:clamp(58px,9.1vw,138px);line-height:.84;letter-spacing:-.075em;font-weight:500;margin:0;max-width:1280px}.hero h1 em{font-style:normal;color:var(--green2)}.hero-bottom{margin-top:clamp(28px,4vw,52px);display:grid;grid-template-columns:1fr .72fr;gap:42px;align-items:end}.hero-lede{font-size:clamp(18px,1.35vw,22px);max-width:780px;color:#dedbd4;letter-spacing:-.02em;margin:0}.hero-actions{justify-self:end;display:flex;gap:10px;align-items:center}.hero-seal{position:absolute;right:var(--pad);top:20%;z-index:2;width:clamp(112px,12vw,182px);aspect-ratio:1;border:1px solid rgba(255,255,255,.28);border-radius:50%;display:grid;place-items:center;text-align:center;font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:#eee}.hero-seal:before{content:"";position:absolute;inset:10px;border:1px solid rgba(83,184,121,.7);border-radius:50%}.hero-seal span{position:relative}
/* SNAPSHOT */
.snapshot{background:var(--paper);color:#10110f;padding:clamp(76px,8vw,128px) 0}.snapshot-head{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px;align-items:start}.snapshot h2{margin:0;font-size:clamp(44px,6vw,88px);line-height:.91;letter-spacing:-.063em;font-weight:500;max-width:1120px}.snapshot h2 em{font-style:normal;color:#2f8e5b}.snapshot-grid{margin-top:clamp(58px,7vw,96px);display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(0,0,0,.2)}.fact{padding:20px 24px 0 0;border-right:1px solid rgba(0,0,0,.16);min-height:148px}.fact:not(:first-child){padding-left:24px}.fact:last-child{border-right:0}.fact small{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#77726b;margin-bottom:18px}.fact strong{display:block;font-size:clamp(19px,1.7vw,27px);line-height:1.08;letter-spacing:-.035em;font-weight:520}.fact a{border-bottom:1px solid #111;padding-bottom:2px}
/* CHALLENGE */
.challenge{padding:clamp(90px,10vw,160px) 0;background:#080908}.challenge-grid{display:grid;grid-template-columns:.76fr 1.24fr;gap:clamp(58px,8vw,132px);align-items:start}.challenge-copy{position:sticky;top:120px}.challenge h2{font-size:clamp(50px,6.2vw,92px);line-height:.91;letter-spacing:-.065em;font-weight:500;margin:18px 0 28px}.challenge h2 span{color:var(--green2)}.challenge p{max-width:600px;color:#c8c6c0;font-size:clamp(17px,1.25vw,20px);margin:0}.challenge-visual{position:relative;min-height:760px}.challenge-visual .main{position:absolute;top:0;right:0;width:90%;height:68%;object-fit:cover;border-radius:4px;filter:saturate(.72) brightness(.8)}.challenge-visual .detail{position:absolute;left:0;bottom:0;width:58%;height:43%;object-fit:cover;border:10px solid #080908;border-radius:4px;box-shadow:0 24px 90px rgba(0,0,0,.55)}.challenge-note{position:absolute;right:3%;bottom:7%;width:min(330px,42%);background:var(--green);color:#07110b;padding:23px;font-size:14px;line-height:1.38}.challenge-note b{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:16px}
/* SELL FLOW */
.sellflow{height:420svh;position:relative;background:#0a0c0b}.sellflow-sticky{position:sticky;top:82px;height:calc(100svh - 82px);display:grid;grid-template-columns:.82fr 1.18fr;overflow:hidden}.sell-copy{padding:clamp(40px,5vw,72px) var(--pad);display:flex;flex-direction:column;border-right:1px solid rgba(255,255,255,.1);background:#0a0c0b}.sell-top{display:flex;justify-content:space-between;gap:20px}.sell-count{font-size:11px;letter-spacing:.16em;color:var(--green2)}.sell-stage{position:relative;flex:1;display:flex;align-items:center}.sell-step{position:absolute;inset:auto 0;opacity:0;visibility:hidden;transform:translateY(18px);transition:opacity .45s var(--ease),transform .55s var(--ease)}.sell-step.active{opacity:1;visibility:visible;transform:none}.sell-step .num{font-size:11px;letter-spacing:.16em;color:#777b77;margin-bottom:18px}.sell-step h3{font-size:clamp(46px,4.8vw,76px);line-height:.91;letter-spacing:-.062em;font-weight:500;margin:0 0 24px}.sell-step p{color:#c9c7c1;max-width:540px;font-size:clamp(16px,1.12vw,19px);margin:0}.sell-tags{margin-top:28px;display:flex;flex-wrap:wrap;gap:8px}.sell-tags span{border:1px solid rgba(255,255,255,.17);padding:8px 11px;font-size:11px;color:#d8d5cf}.sell-progress{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.sell-progress i{height:2px;background:rgba(255,255,255,.12);position:relative;overflow:hidden}.sell-progress i:after{content:"";position:absolute;inset:0;background:var(--green);transform:scaleX(0);transform-origin:left;transition:transform .4s var(--ease)}.sellflow[data-state="0"] .sell-progress i:nth-child(1):after,.sellflow[data-state="1"] .sell-progress i:nth-child(-n+2):after,.sellflow[data-state="2"] .sell-progress i:nth-child(-n+3):after,.sellflow[data-state="3"] .sell-progress i:nth-child(-n+4):after{transform:scaleX(1)}
.sell-visual{position:relative;padding:clamp(28px,3vw,48px);display:grid;place-items:center;background:linear-gradient(145deg,#0d100e,#171b18)}.browser{width:min(860px,96%);aspect-ratio:1.28;background:#f3f2ed;color:#111;border:1px solid rgba(255,255,255,.12);border-radius:5px;box-shadow:0 30px 120px rgba(0,0,0,.55);overflow:hidden}.browser-bar{height:40px;border-bottom:1px solid #d7d5cf;display:flex;align-items:center;gap:7px;padding:0 14px;background:#e9e7e1}.browser-bar i{width:7px;height:7px;border-radius:50%;background:#bbb8b1}.browser-bar span{margin-left:8px;color:#67645e;font-size:10px}.form-ui{height:calc(100% - 40px);padding:clamp(18px,2.2vw,34px);display:flex;flex-direction:column}.form-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d8d6d0;padding-bottom:16px}.form-logo{font-size:17px;letter-spacing:-.04em}.form-head small{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#77736d}.form-title{padding:clamp(18px,2vw,28px) 0 16px}.form-title small{font-size:9px;letter-spacing:.15em;text-transform:uppercase;color:#6a776e}.form-title strong{display:block;font-size:clamp(24px,2.4vw,38px);letter-spacing:-.05em;line-height:1;margin-top:6px}.form-progress{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-bottom:18px}.form-progress i{height:3px;background:#ddd9d1;position:relative;overflow:hidden}.form-progress i:after{content:"";position:absolute;inset:0;background:var(--green);transform:scaleX(0);transform-origin:left;transition:transform .45s var(--ease)}.form-body{flex:1;position:relative;min-height:0}.form-state{position:absolute;inset:0;opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .4s var(--ease),transform .4s var(--ease);display:grid;align-content:start}.form-state.active{opacity:1;visibility:visible;transform:none}.field-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.field{min-height:54px;border:1px solid #d7d4cd;background:#fff;padding:10px 12px}.field small{display:block;font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:#8b877f;margin-bottom:4px}.field strong{font-size:13px;font-weight:520}.field.wide{grid-column:1/-1}.form-cta{margin-top:12px;background:#111;color:#fff;padding:13px 15px;font-size:12px;text-align:center}.offer-card{background:#111;color:#fff;padding:clamp(22px,3vw,40px);min-height:220px;display:flex;flex-direction:column;justify-content:space-between}.offer-card small{font-size:9px;text-transform:uppercase;letter-spacing:.15em;color:#aeb2ad}.offer-card strong{font-size:clamp(31px,4vw,58px);line-height:.93;letter-spacing:-.055em;font-weight:500}.offer-card .offer-row{display:flex;justify-content:space-between;gap:16px;border-top:1px solid rgba(255,255,255,.18);padding-top:14px;font-size:11px;color:#c8cbc7}.inspect{display:grid;grid-template-columns:1fr .8fr;gap:12px}.inspect-main{min-height:210px;background:linear-gradient(140deg,#1c201d,#080908);position:relative;overflow:hidden;padding:20px;color:#fff}.inspect-main:before{content:"";position:absolute;width:190px;height:80px;border:1px solid rgba(83,184,121,.6);border-radius:50%;left:50%;top:51%;transform:translate(-50%,-50%) rotate(-8deg)}.inspect-main:after{content:"";position:absolute;width:240px;height:36px;border-top:2px solid rgba(255,255,255,.55);border-radius:50%;left:50%;top:53%;transform:translate(-50%,-50%) rotate(-8deg)}.inspect-main strong{position:relative;z-index:2;font-size:25px;letter-spacing:-.04em}.inspect-side{display:grid;gap:10px}.check{border:1px solid #d8d5ce;background:#fff;padding:13px}.check small{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.12em;color:#8c887f}.check strong{font-size:12px}.payout{display:grid;grid-template-columns:1.1fr .9fr;gap:12px}.payout-card{background:var(--green);padding:clamp(18px,2.5vw,30px);min-height:210px;display:flex;flex-direction:column;justify-content:space-between}.payout-card small{font-size:9px;letter-spacing:.14em;text-transform:uppercase}.payout-card strong{font-size:clamp(30px,3.5vw,52px);line-height:.95;letter-spacing:-.055em;font-weight:500}.payout-side{display:grid;gap:10px}.payout-side div{border:1px solid #d8d5ce;background:#fff;padding:13px}.payout-side small{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.12em;color:#8c887f}.payout-side strong{font-size:12px}
.sellflow[data-state="0"] .form-progress i:nth-child(1):after,.sellflow[data-state="1"] .form-progress i:nth-child(-n+2):after,.sellflow[data-state="2"] .form-progress i:nth-child(-n+3):after,.sellflow[data-state="3"] .form-progress i:nth-child(-n+4):after{transform:scaleX(1)}
.sell-mobile-visual{display:none}
/* TRUST */
.trust{background:var(--paper);color:#111;padding:clamp(90px,10vw,150px) 0}.trust-head{display:grid;grid-template-columns:.45fr 1.55fr;gap:40px;align-items:start}.trust h2{margin:0;font-size:clamp(48px,6.2vw,92px);line-height:.91;letter-spacing:-.064em;font-weight:500;max-width:1120px}.trust h2 em{font-style:normal;color:#2f8e5b}.trust-list{margin-top:clamp(56px,7vw,92px);border-top:1px solid rgba(0,0,0,.18)}.trust-row{display:grid;grid-template-columns:80px .75fr 1.25fr;gap:30px;align-items:start;padding:27px 0;border-bottom:1px solid rgba(0,0,0,.15)}.trust-row .n{font-size:11px;color:#77736c}.trust-row strong{font-size:clamp(24px,2.4vw,38px);letter-spacing:-.045em;line-height:1}.trust-row p{margin:0;max-width:720px;color:#55514b}
/* AUDIENCE */
.audience{padding:clamp(90px,10vw,150px) 0;background:#080908}.audience-head{display:grid;grid-template-columns:.45fr 1.55fr;gap:40px}.audience h2{font-size:clamp(48px,6.2vw,92px);line-height:.91;letter-spacing:-.064em;font-weight:500;margin:0}.audience h2 span{color:var(--green2)}.audience-grid{margin-top:clamp(54px,7vw,90px);display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}.audience-card{padding:32px 34px 38px 0;border-right:1px solid var(--line)}.audience-card+ .audience-card{padding-left:34px;border-right:0}.audience-card small{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--green2)}.audience-card h3{font-size:clamp(36px,4vw,58px);line-height:.95;letter-spacing:-.055em;font-weight:500;margin:28px 0 18px}.audience-card p{color:#bcbab4;margin:0;max-width:620px;overflow-wrap:anywhere;hyphens:auto}.audience-meta{margin-top:30px;display:flex;flex-wrap:wrap;gap:8px}.audience-meta span{font-size:11px;border:1px solid rgba(255,255,255,.17);padding:8px 10px}
/* BRAND MOMENT */
.brand-moment{background:var(--green);color:#07100a;padding:clamp(70px,7vw,108px) 0 clamp(90px,9vw,140px);overflow:hidden}.brand-lines{padding:0 var(--pad);width:100%}.brand-lines div{font-size:clamp(44px,7.6vw,116px);line-height:.86;letter-spacing:-.07em;font-weight:600;white-space:normal;overflow-wrap:anywhere}.brand-lines .outline{font-weight:500;color:transparent;-webkit-text-stroke:1px rgba(7,16,10,.62);font-size:clamp(38px,6.5vw,98px);margin-top:8px}.brand-grid{margin-top:clamp(58px,7vw,96px);display:grid;grid-template-columns:.45fr 1.55fr;gap:42px}.brand-grid h2{font-size:clamp(44px,5.7vw,84px);line-height:.92;letter-spacing:-.06em;font-weight:500;margin:0 0 22px}.brand-grid p{font-size:clamp(17px,1.3vw,20px);max-width:760px;margin:0;color:#173020}
/* LOCAL */
.local{padding:clamp(90px,10vw,150px) 0;background:#0b0d0c}.local-grid{display:grid;grid-template-columns:1fr .9fr;gap:clamp(58px,8vw,120px);align-items:end}.local h2{font-size:clamp(52px,6.8vw,98px);line-height:.9;letter-spacing:-.065em;font-weight:500;margin:18px 0 28px}.local h2 span{color:var(--green2)}.local p{max-width:670px;color:#c3c0ba;font-size:clamp(17px,1.2vw,20px)}.places{border-top:1px solid var(--line)}.place{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid var(--line)}.place strong{font-size:clamp(20px,2vw,30px);font-weight:500;letter-spacing:-.04em}.place span{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:#858984}
/* LIVE + NEXT */
.live{background:var(--paper);color:#10110f;padding:clamp(90px,10vw,150px) 0}.live-head{display:grid;grid-template-columns:1.25fr .75fr;gap:58px;align-items:end;margin-bottom:clamp(46px,6vw,80px)}.live h2{font-size:clamp(52px,7vw,102px);line-height:.9;letter-spacing:-.065em;font-weight:500;margin:0}.live h2 span{color:#2f8e5b}.live p{margin:0;max-width:500px;color:#5e5a54;font-size:18px}.live-frame{display:block;position:relative;aspect-ratio:16/8;overflow:hidden;background:#111;border-radius:4px}.live-frame img{width:100%;height:100%;object-fit:cover;filter:saturate(.72) brightness(.72);transition:transform 1s var(--ease),filter .7s var(--ease)}.live-frame:after{content:"Live-Projekt öffnen ↗";position:absolute;right:24px;bottom:24px;background:var(--green);color:#06110a;padding:13px 16px;font-size:12px}.live-frame:hover img{transform:scale(1.025);filter:saturate(.9) brightness(.83)}.next{padding:clamp(84px,9vw,138px) 0;background:#070807}.next-grid{display:grid;grid-template-columns:.34fr 1.66fr;gap:48px}.next h2{font-size:clamp(62px,9vw,132px);line-height:.84;letter-spacing:-.074em;font-weight:500;margin:0}.next h2 span{color:var(--red)}.next-row{margin-top:40px;padding-top:20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:40px;align-items:center}.next-row p{margin:0;color:#bdbab4}.next-link{font-size:13px;border-bottom:1px solid #fff;padding-bottom:4px}.footer{border-top:1px solid var(--line);padding:68px 0 28px;background:#070807}.footer-top{display:grid;grid-template-columns:1fr 1fr;gap:70px}.footer-brand{font-size:clamp(44px,6vw,76px);font-weight:600;letter-spacing:-.06em}.footer-top p{color:#8f928d}.footer-map{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.footer-map strong{font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#777b76;display:block;margin-bottom:16px}.footer-map a,.footer-map span{display:block;padding:5px 0;color:#c6c3bd;font-size:13px}.footer-bottom{border-top:1px solid var(--line);margin-top:54px;padding-top:18px;display:grid;grid-template-columns:1fr auto auto;gap:22px;color:#777b76;font-size:10px;text-transform:uppercase;letter-spacing:.12em}.footer-bottom div{display:flex;gap:16px}
