.real-site-showcase{--case:#e81848;background:#0a0a0a;color:#f3efe9;padding:clamp(90px,10vw,160px) 0;border-top:1px solid rgba(255,255,255,.09);border-bottom:1px solid rgba(255,255,255,.09)}
.real-site-shell{width:min(1480px,100%);margin:0 auto;padding:0 clamp(20px,4vw,68px)}
.real-site-head{display:grid;grid-template-columns:minmax(0,1.18fr) minmax(280px,.62fr);gap:clamp(34px,7vw,100px);align-items:end;margin-bottom:clamp(42px,5vw,72px)}
.real-site-kicker{display:block;color:var(--case);font-size:10px;letter-spacing:.18em;text-transform:uppercase;margin-bottom:18px}
.real-site-head h2{font-size:clamp(48px,6.4vw,104px);line-height:.9;letter-spacing:-.065em;font-weight:520;margin:0;max-width:980px}
.real-site-head p{margin:0;color:#aaa59e;font-size:clamp(16px,1.15vw,19px);line-height:1.55;max-width:520px}
.real-site-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.real-site-card{display:block;color:inherit;text-decoration:none;min-width:0;background:#101010;border:1px solid rgba(255,255,255,.14);border-radius:6px;overflow:hidden;transition:transform .6s cubic-bezier(.16,1,.3,1),border-color .4s ease}
